<script lang="ts">import { enhance } from "$app/forms"; import BlogShell from "$lib/components/BlogShell.svelte"; import type { PageProps } from "./$types"; let { data }: PageProps = $props();</script>
<svelte:head><title>Blog dashboard | Renhet Studio</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<BlogShell profile={data.profile}><section class="dashboard-page"><header class="dashboard-header"><div><p class="dashboard-kicker">Publishing</p><h1>Blog dashboard</h1><p>Draft, schedule, publish, and moderate from one place.</p></div><a href="/blog/dashboard/posts/new">Write a new story</a></header>
  <section class="dashboard-section"><div class="dashboard-section-heading"><h2>Stories</h2><span>{data.posts.length} total</span></div>{#if !data.posts.length}<p class="dashboard-empty">No posts yet. Create the first story.</p>{:else}<div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>Story</th><th>Category</th><th>Status</th><th>Updated</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>{#each data.posts as post}<tr><td><a href={`/blog/dashboard/posts/${post.id}`}>{post.title}</a><small>/{post.slug}</small></td><td>{post.category}</td><td><span class={`status-badge status-${post.status}`}>{post.status}{post.status === "published" && post.published_at && new Date(post.published_at) > new Date() ? " · scheduled" : ""}</span></td><td>{new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(post.updated_at))}</td><td><div class="dashboard-actions"><a href={`/blog/dashboard/posts/${post.id}`}>Edit</a><a href={`/blog/preview/${post.id}`} target="_blank" rel="noreferrer">Preview</a><form method="POST" action="?/delete" use:enhance onsubmit={(event) => { if (!confirm(`Delete “${post.title}”? This cannot be undone.`)) event.preventDefault(); }}><input type="hidden" name="id" value={post.id} /><button class="danger-button" type="submit">Delete</button></form></div></td></tr>{/each}</tbody></table></div>{/if}</section>
  <section class="dashboard-section" id="moderation"><div class="dashboard-section-heading"><h2>Comment moderation</h2><span>{data.comments.length} pending</span></div>{#if !data.comments.length}<p class="dashboard-empty">The moderation queue is clear.</p>{:else}<ul class="moderation-list">{#each data.comments as comment}<li><div><strong>{comment.display_name}</strong><time datetime={comment.created_at}>{new Intl.DateTimeFormat("en", { dateStyle: "medium", timeStyle: "short" }).format(new Date(comment.created_at))}</time></div><p>{comment.body}</p><div class="moderation-actions"><form method="POST" action="?/moderate" use:enhance><input type="hidden" name="id" value={comment.id} /><input type="hidden" name="status" value="approved" /><button type="submit">Approve</button></form><form method="POST" action="?/moderate" use:enhance><input type="hidden" name="id" value={comment.id} /><input type="hidden" name="status" value="rejected" /><button class="danger-button" type="submit">Reject</button></form></div></li>{/each}</ul>{/if}</section>
</section></BlogShell>
